# Corrected analysis of secondary diagonal through (15,0) with r+c=15

h, w = 16, 16
cand = [[0]*w for _ in range(h)]

print("Main diagonal positions (r-c=2 mod 16):")
for i in range(4):
    r = (0+i)%h
    c = (14+i)%w
    print(f"  Index {i}: ({r}, {c})")

print("\nSecondary anti-diagonal positions (r+c=15 mod 16) through (15,0):")
anti_indices = []
for r in range(16):
    c = (r + 15) % 16  # This gives r+c=15 mod 16
    if (r + c) % 16 == 15:
        anti_indices.append((r, c))

for idx, (r, c) in enumerate(anti_indices[:6]):
    print(f"  Index {idx}: ({r}, {c}), sum={r+c}")

# Build with pattern: first 2 cells YELLOW, rest WHITE for BOTH diagonals
for i in range(h):
    r = (0+i)%h
    c = (14+i)%w
    cand[r][c] = 9 if i < 2 else 1

for idx, (r, c) in enumerate(anti_indices):
    # Skip if already set on main diagonal
    if (r - c) % 16 == 2:
        continue
    if idx < 2:
        cand[r][c] = 9
    else:
        cand[r][c] = 1

print("\n\nFinal grid:")
for row in cand:
    print(' '.join(f'{x}' for x in row))
